def delays(attempts, base, cap):
    """Return a list of retry delays for exponential backoff.

    The list contains (attempts - 1) values where the i-th delay
    (0-indexed) is min(base * 2**i, cap).
    """
    if not isinstance(attempts, int) or isinstance(attempts, bool):
        raise ValueError("attempts must be an integer")
    if not isinstance(base, int) or isinstance(base, bool):
        raise ValueError("base must be an integer")
    if not isinstance(cap, int) or isinstance(cap, bool):
        raise ValueError("cap must be an integer")
    if attempts < 1:
        raise ValueError("attempts must be >= 1")
    if base < 0:
        raise ValueError("base must be >= 0")
    if cap < 0:
        raise ValueError("cap must be >= 0")
    return [min(base * 2**i, cap) for i in range(attempts - 1)]
