def flatten(value):
    """Flatten a nested dictionary with string keys into dot-separated keys.

    - Lists and scalar leaves are preserved as values.
    - An empty dictionary leaf is represented as {} at its path.
    - An empty root produces {}.
    - The input is not mutated.
    """
    if not isinstance(value, dict):
        return value
    if not value:
        return {}
    result = {}
    for key, val in value.items():
        if isinstance(val, dict) and val:
            sub = flatten(val)
            for sub_key, sub_val in sub.items():
                result[f"{key}.{sub_key}"] = sub_val
        else:
            result[key] = val
    return result
