def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    - Raises ValueError if the path is not absolute (does not start with '/').
    - Collapses repeated slashes.
    - Ignores single-dot ('.') components.
    - Resolves double-dot ('..') components without going above root.
    - Returns '/' for the root.
    - Never returns a trailing slash for non-root paths.
    - Performs no filesystem access.
    """
    if not isinstance(path, str) or not path.startswith("/"):
        raise ValueError(f"Expected an absolute POSIX path, got: {path!r}")

    stack: list[str] = []
    for part in path.split("/"):
        if part == "" or part == ".":
            continue
        elif part == "..":
            if stack:
                stack.pop()
            # else: already at root, ignore
        else:
            stack.append(part)

    if not stack:
        return "/"
    return "/" + "/".join(stack)
```

