import copy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries.

    Overlay values replace base values. If both values for a key are dicts,
    they are merged recursively. Lists and None are replaced wholesale.
    A None overlay value does not delete the key; it sets the value to None.
    The result is deep-independent of both inputs (no aliasing).
    """
    result = {}

    for key, value in base.items():
        result[key] = copy.deepcopy(value)

    for key, value in overlay.items():
        if (
            key in result
            and isinstance(result[key], dict)
            and isinstance(value, dict)
        ):
            result[key] = merge(result[key], value)
        else:
            result[key] = copy.deepcopy(value)

    return result
