def normalize(path):
    """Normalize an absolute POSIX-like path.

    - Collapses repeated slashes.
    - Removes '.' components.
    - Resolves '..' without going above root.
    - Returns '/' for the root.
    - Never returns a trailing slash (except the root itself).
    - Raises ValueError if the path is not absolute.
    """
    if not path.startswith('/'):
        raise ValueError(f"not an absolute path: {path!r}")

    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    if not stack:
        return '/'
    return '/' + '/'.join(stack)
