import heapq


def order(deps):
    # Collect all nodes (keys and any prerequisite-only nodes)
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    # Build in-degree map and adjacency list (prereq -> dependents)
    in_degree = {node: 0 for node in nodes}
    adj = {node: [] for node in nodes}

    for node, prereqs in deps.items():
        for p in set(prereqs):
            adj[p].append(node)
            in_degree[node] += 1

    # Min-heap of currently ready nodes (in-degree 0)
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in adj[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
